import unittest

COUNTER_MODULUS = 65536      # 16-bit counter: values 0..65535
TICKS_PER_SECOND = 10_000    # 1 tick = 0.0001 s


def gate_time_s(start_tick, stop_tick):
    """Return the elapsed sprint time in seconds between two latched ticks.

    The timer is a free-running 16-bit counter at 10,000 ticks per second
    that rolls over from 65535 to 0 every 6.5536 s. Because a sprint always
    takes less than 6 s, the counter can roll over at most once between the
    latches, so stop_tick may be numerically smaller than start_tick. The
    elapsed ticks are computed modulo 65536, which gives the correct count
    whether or not a rollover occurred.

    Raises ValueError if either input is not an integer in 0..65535.
    """
    for name, value in (("start_tick", start_tick), ("stop_tick", stop_tick)):
        # bool is a subclass of int, but True/False are not valid tick values.
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError(f"{name} must be an integer, got {value!r}")
        if not 0 <= value < COUNTER_MODULUS:
            raise ValueError(
                f"{name} must be in the range 0-{COUNTER_MODULUS - 1}, got {value!r}"
            )

    elapsed_ticks = (stop_tick - start_tick) % COUNTER_MODULUS
    return elapsed_ticks / TICKS_PER_SECOND


class GateTimeTests(unittest.TestCase):
    def test_no_rollover(self):
        self.assertEqual(gate_time_s(0, 50000), 5.0)

    def test_zero_elapsed(self):
        self.assertEqual(gate_time_s(1000, 1000), 0.0)

    def test_rollover(self):
        self.assertEqual(gate_time_s(60000, 4464), 1.0)

    def test_rollover_single_tick(self):
        self.assertEqual(gate_time_s(65535, 0), 0.0001)

    def test_returns_float(self):
        self.assertIsInstance(gate_time_s(0, 50000), float)
        self.assertIsInstance(gate_time_s(1000, 1000), float)

    def test_out_of_range_raises(self):
        for start, stop in ((-1, 100), (100, -1), (65536, 0), (0, 65536)):
            with self.subTest(start=start, stop=stop):
                with self.assertRaises(ValueError):
                    gate_time_s(start, stop)

    def test_non_integer_raises(self):
        for start, stop in ((1.0, 100), (100, 2.5), ("100", 200), (None, 0), (True, 0)):
            with self.subTest(start=start, stop=stop):
                with self.assertRaises(ValueError):
                    gate_time_s(start, stop)


if __name__ == "__main__":
    unittest.main()
